UPDATE response_policy
SET status='active', approved_by=#{actorId}, reviewed_by=#{actorId}, reviewed_at=UTC_TIMESTAMP(3),
    decision_reason=#{reason}
WHERE id=#{id} AND status='pending' AND created_by IS NOT NULL AND created_by<>#{actorId}

UPDATE response_policy
SET status='rejected', reviewed_by=#{actorId}, reviewed_at=UTC_TIMESTAMP(3), decision_reason=#{reason}
WHERE id=#{id} AND status='pending' AND created_by IS NOT NULL AND created_by<>#{actorId}
